package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class EmployeeCasesBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String group;
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String user:new String[]{"EmployeeBrowserAgent","HrBrowserAgent"})Service.createAccount(db,map("name",user,"role","agent","password",WorkflowSupport.PASSWORD));group=Service.create(db,"sys_user_group",map("short_description","Employee browser HR team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,RecordAccess.owner(db,"HrBrowserAgent"));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var adminContext=browser.newContext();var employeeContext=browser.newContext();var staffContext=browser.newContext()){
   var admin=adminContext.newPage();h.login(admin,"admin");for(String table:new String[]{"hr_case","customer_case"}){admin.navigate(h.base()+"/workspace/"+table);assertThat(admin.locator("a[href='/record/"+table+"/new']")).hasCount(0);}
   admin.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Manage employee services").setExact(true)).press("Enter");admin.getByLabel("Account username").fill("EmployeeBrowserAgent");admin.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Find account")).press("Enter");admin.getByLabel("Employee department").fill("Engineering");admin.getByLabel("Employee enrollment").selectOption("true");admin.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save employee profile")).press("Enter");var create=admin.locator("section").filter(new Locator.FilterOptions().setHas(admin.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Create an employee service").setExact(true))));create.getByLabel("Service name").fill("Browser benefit enrolment");create.getByLabel("Service description").fill("Review employee benefits privately");create.getByLabel("Department audience").fill("Engineering");create.getByLabel("HR service team").selectOption(group);create.getByLabel("Service availability").selectOption("true");create.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Save employee service")).press("Enter");assertThat(admin.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Browser benefit enrolment").setExact(true))).hasCount(1);ReleaseBrowserAcceptance.accessible(admin);admin.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/employee-services-admin-light.png")).setFullPage(true));
   var employee=employeeContext.newPage();h.login(employee,"EmployeeBrowserAgent");employee.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Employee services").setExact(true)).press("Enter");employee.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Browser benefit enrolment").setExact(true)).press("Enter");employee.getByLabel("Request summary").fill("Benefit enrolment <script>");employee.getByLabel("How can HR help?").fill("Please explain my benefit choices\nEmployee-only request details");ReleaseBrowserAcceptance.accessible(employee);employee.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/employee-intake-light.png")).setFullPage(true));employee.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Submit employee case")).press("Enter");String id=employee.url().substring(employee.url().lastIndexOf('/')+1);assertThat(employee.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Benefit enrolment <script>").setExact(true))).hasCount(1);
   var staff=staffContext.newPage();h.login(staff,"HrBrowserAgent");staff.navigate(h.base()+"/record/hr_case/"+id);staff.locator("select[name=state]").selectOption("working");staff.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →")).press("Enter");staff.getByLabel("Add an internal note").fill("PRIVATE HR staff assessment");staff.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Add note").setExact(true)).press("Enter");staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Employee conversation").setExact(true)).press("Enter");staff.getByLabel("Public message").fill("Here are your current benefit choices <script>safe</script>");staff.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Send public message")).press("Enter");ReleaseBrowserAcceptance.accessible(staff);staff.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/employee-hr-conversation-light.png")).setFullPage(true));
   employee.reload();assertThat(employee.locator(".breadcrumb")).containsText("Employee services");assertThat(employee.locator("main")).containsText("In progress");assertThat(employee.locator("main")).containsText("Here are your current benefit choices");assertThat(employee.locator("main")).not().containsText("PRIVATE HR staff assessment");employee.getByLabel("Public message").fill("Thank you; I selected my benefit option");employee.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Send public message")).press("Enter");employee.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");employee.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(employee);assertEquals(false,employee.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(employee.locator("main script")).hasCount(0);employee.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/employee-follow-up-dark.png")).setFullPage(true));
   staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("HR case workspace")).press("Enter");staff.locator("select[name=state]").selectOption("closed");staff.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →")).press("Enter");employee.reload();assertThat(employee.locator("main")).containsText("Closed complete");assertThat(employee.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Send public message"))).hasCount(0);
  }
 }
}
